(function () {
/**
 * 拼多多 · 整数 VID 全空间扫描器（自适应速率版）
 * ==================================================================
 * 回答三个问题：
 *   1) vid 上界不是固定的 600 万 —— vid 是全平台属性取值的共享 ID 空间，会随时间增长。
 *      因此本脚本的扫描上界 S.to 是**动态**的：每次存检查点时用"当前观测到的最大 vid"抬高它。
 *   2) 没有"一键拿全"的接口捷径（策展品牌表被服务端写死 50 条且 total 造假）。
 *      要保证完整，只能逐整数扫；本脚本把代价压到最低。
 *   3) 速率自适应：AIMD（加性增 / 乘性减）自动找到"不触发限流的最快速度"并持续贴着它跑。
 *
 * 完整性口径：
 *   ✅ 扫过的整数区间内 100% 完整（不依赖品牌库枚举）
 *   ❌ 未扫区间不保证；S.to 会随观测到的最大 vid 自动抬高
 *   判定条件：finalized=true 且 pendingFailed=0 且 next > to
 *
 * 用法：
 *   await runAdaptiveSweep(5908)              // 自适应全扫（默认从 1 到当前观测最大 vid）
 *   await runAdaptiveSweep(5908, { from: 1, to: 5954043 })
 *   arkAdaptStatus()                          // 进度 / 当前速率 / 学到的并发上限 / ETA
 *   arkAdaptExport(5908)                      // 导出 CSV
 *   arkAdaptStop()                            // 停止（会先存检查点）
 */

const ARK_A_REF = 310;
const ARK_A_KEY = c => 'ark_adapt_' + c;

function arkASleep(ms) { return new Promise(r => setTimeout(r, ms)); }

function arkObservedMaxVid() {
  const map = window.__brandMap2 || (window.__big && window.__big.map) || {};
  let mx = 0;
  for (const k in map) { const v = +k; if (v > mx) mx = v; }
  return mx;
}

function arkAdaptSave(catId) {
  const S = window.__arkAdapt;
  if (!S) return null;
  try {
    localStorage.setItem(ARK_A_KEY(catId), JSON.stringify({
      next: S.next, to: S.to, tested: S.tested, ok: S.ok, must: S.must, notShow: S.notShow,
      failed: S.failed, throttled: S.throttled, conc: S.conc, delay: S.delay,
      bestRate: S.bestRate, ceilingConc: S.ceilingConc, ts: Date.now()
    }));
    return 'saved';
  } catch (e) { return 'fail:' + e.message; }
}

async function runAdaptiveSweep(catId, opts) {
  opts = opts || {};
  const minConc = opts.minConc || 1;
  const maxConc = opts.maxConc || 32;
  const startFrom = opts.from || 1;
  let saved = null;
  if (opts.resume !== false) { try { saved = JSON.parse(localStorage.getItem(ARK_A_KEY(catId)) || 'null'); } catch (e) { saved = null; } }
  const obsMax = arkObservedMaxVid();
  const defaultTo = opts.to || Math.max(obsMax, 1000000);

  const S = window.__arkAdapt = (saved && saved.next > startFrom && saved.next <= saved.to)
    ? Object.assign(saved, { catId: catId, done: false, resumed: true, started: Date.now(), active: 0, stop: false,
        window: { ok: 0, th: 0 }, lastAdjust: Date.now(), rateWin: [], finalized: false })
    : { catId: catId, next: startFrom, to: defaultTo, tested: 0, ok: 0, must: [], notShow: [], failed: [],
        throttled: 0, conc: opts.startConc || 4, delay: 0, bestRate: 0, ceilingConc: 0,
        done: false, resumed: false, started: Date.now(), active: 0, stop: false,
        window: { ok: 0, th: 0 }, lastAdjust: Date.now(), rateWin: [], finalized: false };

  S.stop = false;

  // ---- 单次请求（双限流码退避） ----
  const one = async (vid) => {
    for (let a = 0; a < 8; a++) {
      try {
        const r = await fetch('/glide/v2/mms/query/rules/limit/new', {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
          body: JSON.stringify({ cat_id: catId, goods_type: 1, goods_properties: [{ ref_pid: ARK_A_REF, vid: vid }] })
        });
        const j = await r.json();
        if (j && j.success) return { must: j.result.is_must_fake_one_lose_ten === true, notShow: j.result.is_not_show_fake_one_lose_ten === true };
        const code = String(j && (j.error_code || j.errorCode));
        if (code === '55555' || code === '40002') { S.throttled++; S.window.th++; await arkASleep(Math.min(1000 * (a + 1), 10000)); continue; }
        return { other: code };
      } catch (e) { await arkASleep(500 * (a + 1)); }
    }
    return null;
  };

  // ---- 速率控制器：AIMD ----
  const controller = setInterval(() => {
    if (S.done || S.stop) return;
    const now = Date.now();
    const span = (now - S.lastAdjust) / 1000;
    if (span < 6) return;
    const okN = S.window.ok, thN = S.window.th;
    const rate = okN / span * 60;               // 次/分钟
    if (rate > S.bestRate) S.bestRate = Math.round(rate);
    S.rateWin.push({ t: now, rate: Math.round(rate), conc: S.conc, th: thN });
    if (S.rateWin.length > 60) S.rateWin.shift();
    if (thN === 0) {
      // 无节流 → 加性增（并发 +1，单步延迟减半）
      if (S.conc < maxConc) S.conc++;
      if (S.delay > 0) S.delay = Math.max(0, Math.round(S.delay * 0.6));
    } else {
      // 有节流 → 乘性减（并发减半），并记录触发上限
      S.ceilingConc = Math.max(S.ceilingConc, S.conc);
      S.conc = Math.max(minConc, Math.floor(S.conc * 0.5));
      S.delay = Math.min(2000, S.delay + 120);
      // 回退：把本窗口失败的影响算进速率
    }
    S.window.ok = 0; S.window.th = 0; S.lastAdjust = now;
  }, 3000);

  // ---- 动态工作池：worker 数跟随 S.conc ----
  let sinceCkpt = 0;
  const worker = async (id) => {
    while (!S.stop) {
      if (id >= S.conc) { await arkASleep(250); continue; }
      if (S.next > S.to) return;
      const v = S.next++;
      const r = await one(v);
      S.tested++;
      if (r === null) { S.failed.push(v); }
      else { S.ok++; S.window.ok++; if (r.must) S.must.push(v); if (r.notShow) S.notShow.push(v); }
      if (S.delay > 0) await arkASleep(S.delay);
      if (++sinceCkpt >= 1000) {
        sinceCkpt = 0;
        // 动态抬高上界：vid 空间会增长
        const m = arkObservedMaxVid();
        if (m > S.to) S.to = m;
        arkAdaptSave(catId);
      }
    }
  };
  // 预起 32 个逻辑 worker，靠 id 与 S.conc 比较实现动态扩缩
  const pool = Array.from({ length: maxConc }, (_, i) => worker(i));

  await Promise.all(pool);
  clearInterval(controller);

  // ---- 失败补扫（保持自适应） ----
  let rounds = 0;
  while (S.failed.length && rounds < 8 && !S.stop) {
    rounds++;
    await arkASleep(5000);
    const retry = S.failed.splice(0);
    let i = 0;
    const rw = async () => { while (i < retry.length && !S.stop) { const v = retry[i++]; const r = await one(v); S.tested++; if (r === null) S.failed.push(v); else { S.ok++; if (r.must) S.must.push(v); if (r.notShow) S.notShow.push(v); } if (S.delay > 0) await arkASleep(S.delay); } };
    await Promise.all(Array.from({ length: S.conc }, rw));
  }

  S.done = true; S.finalized = S.failed.length === 0; S.finishedAt = Date.now();
  arkAdaptSave(catId);

  // 自检：已知强制 vid 必须命中
  const known = [11646, 132, 17779, 17780, 17781, 17782, 17787, 17789, 17795, 31130, 2687, 33847, 450, 101, 8906, 17784, 22254, 71272, 17790];
  const seen = new Set(S.must);
  S.selfCheck = { known: known.length, missing: known.filter(v => !seen.has(v)) };
  S.learned = { bestConc: S.ceilingConc, bestRatePerMin: S.bestRate, finalDelay: S.delay };
  if (opts.download) arkAdaptExport(catId);
  return S;
}

function arkAdaptStop() {
  const S = window.__arkAdapt;
  if (!S) return 'no sweep';
  S.stop = true; S.done = true;
  arkAdaptSave(S.catId);
  return arkAdaptStatus();
}

function arkAdaptStatus() {
  const S = window.__arkAdapt;
  if (!S) return 'no sweep';
  const span = S.to - 1;
  const done = S.next - 1;
  const mins = (Date.now() - S.started) / 60000;
  const rate = S.tested / Math.max(mins, 0.5);
  return {
    catId: S.catId, resumed: S.resumed, range: '1-' + S.to,
    scanned: done, span: span, pct: Math.round(done / span * 1000) / 10 + '%',
    tested: S.tested, ok: S.ok, must: S.must.length, pendingFailed: S.failed.length,
    throttled: S.throttled, concNow: S.conc, delayNow: S.delay,
    bestRatePerMin: S.bestRate, ceilingConcSeen: S.ceilingConc,
    perMin: Math.round(rate), etaMin: rate > 0 ? Math.round((span - done) / rate) : null,
    etaHours: rate > 0 ? Math.round((span - done) / rate / 60 * 10) / 10 : null,
    done: S.done, finalized: S.finalized, selfCheck: S.selfCheck || null, learned: S.learned || null
  };
}

function arkAdaptExport(catId, filename) {
  const S = window.__arkAdapt;
  if (!S) return null;
  const map = window.__brandMap2 || (window.__big && window.__big.map) || {};
  const rows = S.must.slice().sort((a, b) => a - b).map(v => [catId, v, map[v] === undefined ? '' : map[v]]);
  arkAdaptCsv(filename || ('强制假一赔十_自适应全扫_' + catId + '.csv'), rows);
  return { catId: catId, forced: rows.length, scannedTo: S.next - 1, tested: S.tested };
}

function arkAdaptCsv(filename, rows, header) {
  header = header || ['cat_id', 'brand_vid', 'brand_name'];
  const q = s => '"' + String(s === undefined || s === null ? '' : s).replace(/"/g, '""') + '"';
  const csv = '\uFEFF' + [header.map(q).join(',')].concat(rows.map(r => r.map(q).join(','))).join('\r\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob); a.download = filename;
  document.body.appendChild(a); a.click();
  setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 3000);
}

